import { Column, CreateDateColumn, Entity, PrimaryColumn } from "typeorm";
import type { DevicePlatform } from "@/modules/identity/domain/device";

@Entity("tb_devices")
export class DeviceOrmEntity {
  // Generated by the API: it is part of the refresh token.
  @PrimaryColumn("uuid", { name: "idtb_devices" })
  id!: string;

  @Column({ name: "idtb_users", type: "uuid" })
  userId!: string;

  @Column({ type: "varchar", length: 60 })
  name!: string;

  @Column({ type: "varchar", length: 10 })
  platform!: DevicePlatform;

  @Column({ name: "refresh_secret_hash", type: "varchar", length: 64 })
  refreshSecretHash!: string;

  @Column({ name: "expires_at", type: "timestamptz" })
  expiresAt!: Date;

  @Column({ name: "last_seen_at", type: "timestamptz" })
  lastSeenAt!: Date;

  @Column({ name: "revoked_at", type: "timestamptz", nullable: true })
  revokedAt!: Date | null;

  @CreateDateColumn({ name: "created_at", type: "timestamptz" })
  createdAt!: Date;
}
